#pragma once
#include "kstationFlashStateTask.h"
namespace kstation {
// Decimal rendering works against live scratch memory; width two deliberately
// allows three digits to reach the byte preceding the scratch buffer.
class NumericDisplayTask final {
public:
 enum class Kind {ZeroTwo,SpaceTwo,SpaceThree,Format,String};
 enum class Stage {RetainValue,RetainPointer,RetainScratch,Width,Padding,FormatChild,BindString,StringChild,RestoreScratch,RestorePointer,RestoreValue,Return,BindBuffer,Fill,AdvanceFill,DecrementFill,RepeatFill,ClearTerminator,Terminate,Radix,ClearHigh,Divide,Ascii,Backtrack,Digit,TestQuotient,RepeatDigits,RetainCharacter,ReadCharacter,SelectEnd,CharacterChild,RepeatString,RestoreCharacter,Complete};
 NumericDisplayTask(Kind kind=Kind::ZeroTwo,uint8_t value=0,uint8_t width=2,uint8_t padding=0x20,uint32_t source=0):kind_(kind),stage_(kind==Kind::Format?Stage::BindBuffer:kind==Kind::String?Stage::RetainCharacter:Stage::RetainValue),value_(value),width_(width),padding_(padding),pointer_(source){}
 Kind kind()const{return kind_;}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}uint32_t pointer()const{return pointer_;}uint8_t padding()const{return padding_;}uint8_t digit()const{return digit_;}uint8_t value()const{return value_;}uint8_t width()const{return width_;}uint8_t character()const{return character_;}
 unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::RetainValue:case Stage::RetainCharacter:return c.pushWord;case Stage::RetainPointer:case Stage::RetainScratch:return c.pushLong;case Stage::RestoreScratch:case Stage::RestorePointer:return c.popLong;case Stage::RestoreCharacter:case Stage::RestoreValue:return c.popWord;case Stage::BindString:case Stage::BindBuffer:return 9;case Stage::FormatChild:return kind_==Kind::SpaceThree?c.shortCall:c.call;case Stage::StringChild:case Stage::CharacterChild:return c.call;case Stage::Fill:case Stage::Terminate:case Stage::Digit:return 3+c.write;case Stage::ReadCharacter:return 5+c.read;case Stage::Divide:return 15;case Stage::Return:return c.ret;default:return 3;}}
 template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::Width:width_=kind_==Kind::SpaceThree?3:2;break;case Stage::Padding:padding_=kind_==Kind::ZeroTwo?0x30:0x20;break;case Stage::FormatChild:waiting_=true;break;case Stage::StringChild:waiting_=true;break;case Stage::Return:next=Stage::Complete;break;case Stage::BindBuffer:pointer_=0xfffe3e;break;case Stage::Fill:write(pointer_,padding_);break;case Stage::AdvanceFill:++pointer_;break;case Stage::DecrementFill:--width_;break;case Stage::RepeatFill:if(width_)next=Stage::Fill;break;case Stage::ClearTerminator:padding_=0;break;case Stage::Terminate:write(pointer_,0);break;case Stage::Divide:digit_=value_%10;value_/=10;break;case Stage::Ascii:digit_+=0x30;break;case Stage::Backtrack:--pointer_;break;case Stage::Digit:write(pointer_,digit_);break;case Stage::RepeatDigits:next=value_?Stage::ClearHigh:Stage::Return;break;case Stage::ReadCharacter:character_=uint8_t(read(pointer_++));break;case Stage::SelectEnd:if(!character_)next=Stage::RestoreCharacter;break;case Stage::CharacterChild:waiting_=true;break;case Stage::RepeatString:next=Stage::ReadCharacter;break;case Stage::RestoreCharacter:next=Stage::Return;break;default:break;}stage_=next;return cost;}
private:Kind kind_;Stage stage_;uint8_t value_,width_,padding_,digit_=0,character_=0;uint32_t pointer_;bool waiting_=false;
};
}
